def ledger(ops: list[str]) -> tuple[dict[str, int], list[int]]:
    balances = {}
    frozen = set()
    history = []
    rejected = []

    for index, operation in enumerate(ops):
        tokens = operation.split(" ")
        if not tokens or any(token == "" for token in tokens):
            rejected.append(index)
            continue

        verb = tokens[0]
        success = False
        action = None

        if verb == "open" and len(tokens) == 3:
            account, amount_text = tokens[1], tokens[2]
            if amount_text.isdigit() and account not in balances:
                balances[account] = int(amount_text)
                action = ("open", account)
                success = True

        elif verb == "deposit" and len(tokens) == 3:
            account, amount_text = tokens[1], tokens[2]
            if amount_text.isdigit() and int(amount_text) > 0 and account in balances:
                amount = int(amount_text)
                balances[account] += amount
                action = ("balance", account, amount)
                success = True

        elif verb == "withdraw" and len(tokens) == 3:
            account, amount_text = tokens[1], tokens[2]
            if amount_text.isdigit() and int(amount_text) > 0 and account in balances and account not in frozen:
                amount = int(amount_text)
                if balances[account] >= amount:
                    balances[account] -= amount
                    action = ("balance", account, -amount)
                    success = True

        elif verb == "transfer" and len(tokens) == 4:
            source, target, amount_text = tokens[1], tokens[2], tokens[3]
            if (amount_text.isdigit() and int(amount_text) > 0 and source != target
                    and source in balances and target in balances and source not in frozen):
                amount = int(amount_text)
                if balances[source] >= amount:
                    balances[source] -= amount
                    balances[target] += amount
                    action = ("transfer", source, target, amount)
                    success = True

        elif verb == "freeze" and len(tokens) == 2:
            account = tokens[1]
            if account in balances and account not in frozen:
                frozen.add(account)
                action = ("freeze", account, False)
                success = True

        elif verb == "unfreeze" and len(tokens) == 2:
            account = tokens[1]
            if account in balances and account in frozen:
                frozen.remove(account)
                action = ("freeze", account, True)
                success = True

        elif verb == "undo" and len(tokens) == 1:
            if history:
                action = history.pop()
                kind = action[0]
                if kind == "open":
                    balances.pop(action[1], None)
                    frozen.discard(action[1])
                elif kind == "balance":
                    balances[action[1]] -= action[2]
                elif kind == "transfer":
                    _, source, target, amount = action
                    balances[source] += amount
                    balances[target] -= amount
                elif kind == "freeze":
                    account, was_frozen = action[1], action[2]
                    if was_frozen:
                        frozen.add(account)
                    else:
                        frozen.discard(account)
                success = True

        if success:
            if verb != "undo":
                history.append(action)
        else:
            rejected.append(index)

    return balances, rejected
